cat > /tmp/fontcheck.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('http://127.0.0.1:37007/orders.html');
await page.evaluate(() => document.fonts.ready);
console.log('fonts loaded check:', await page.evaluate(() => ({
  check: document.fonts.check('16px "Acme Sans"'),
  status: document.fonts.status,
  faces: [...document.fonts].map(f => ({family:f.family, weight:f.weight, status:f.status})),
})));
const client = await page.context().newCDPSession(page);
await client.send('DOM.enable'); await client.send('CSS.enable');
const {root} = await client.send('DOM.getDocument');
const {nodeId} = await client.send('DOM.querySelector',{nodeId:root.nodeId, selector:'.brand'});
const fonts = await client.send('CSS.getPlatformFontsForNode',{nodeId});
console.log('brand fonts:', JSON.stringify(fonts));
const {nodeId: n2} = await client.send('DOM.querySelector',{nodeId:root.nodeId, selector:'.nav-link'});
console.log('nav fonts:', JSON.stringify(await client.send('CSS.getPlatformFontsForNode',{nodeId:n2})));
const {nodeId: n3} = await client.send('DOM.querySelector',{nodeId:root.nodeId, selector:'h1'});
console.log('h1 fonts:', JSON.stringify(await client.send('CSS.getPlatformFontsForNode',{nodeId:n3})));
await browser.close();
EOF
PORT=37007 node server.js >/tmp/srv.log 2>&1 &
sleep 1
node /tmp/fontcheck.mjs

cat > fontcheck.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('http://127.0.0.1:37007/orders.html');
await page.evaluate(() => document.fonts.ready);
console.log('fonts loaded check:', await page.evaluate(() => ({
  check: document.fonts.check('16px "Acme Sans"'),
  status: document.fonts.status,
  faces: [...document.fonts].map(f => ({family:f.family, weight:f.weight, status:f.status})),
})));
const client = await page.context().newCDPSession(page);
await client.send('DOM.enable'); await client.send('CSS.enable');
const {root} = await client.send('DOM.getDocument');
for (const sel of ['.brand','.nav-link','h1','tbody td','.pill']) {
  const {nodeId} = await client.send('DOM.querySelector',{nodeId:root.nodeId, selector:sel});
  if (nodeId) console.log(sel, JSON.stringify(await client.send('CSS.getPlatformFontsForNode',{nodeId})));
}
await browser.close();
EOF
