python3 - <<'EOF'
from PIL import Image
import numpy as np
from collections import deque
def comps(mask):
    H,W=mask.shape; seen=np.zeros_like(mask,bool); out=[]
    for y in range(H):
        for x in range(W):
            if mask[y,x] and not seen[y,x]:
                q=deque([(y,x)]); seen[y,x]=True; pts=[]
                while q:
                    cy,cx=q.popleft(); pts.append((cy,cx))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=cy+dy,cx+dx
                            if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=True; q.append((ny,nx))
                ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
                out.append((len(pts),min(xs),min(ys),max(xs),max(ys)))
    out.sort(reverse=True)
    return out
for name in ['home-desktop','orders-desktop','about-phone']:
    d=f'test-results/visual-{name}'; b=name.split('-')[0]
    a=np.asarray(Image.open(f'{d}/{b}-actual.png').convert('RGB')).astype(int)
    e=np.asarray(Image.open(f'{d}/{b}-expected.png').convert('RGB')).astype(int)
    m=(np.abs(a-e).max(axis=2)>8)
    cs=comps(m)
    print(name,'components',len(cs),'total px',m.sum())
    for c in cs[:12]: print('  ',c)
EOF

