  });
  return out;
});
for (const d of data) {
  if (d.y>1250 && d.y<1320) console.log(JSON.stringify(d));
}
console.log('--- sample weights');
const seen=new Set();
for (const d of data) { const k=d.fw+'|'+d.fs; if(!seen.has(k)){seen.add(k); console.log(d.fw,d.fs,d.tag,d.cls,JSON.stringify(d.text));} }
await browser.close();
EOF
