import { chromium } from 'playwright';
import { PNG } from 'pngjs';
import fs from 'fs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
await page.goto('http://127.0.0.1:37007/');
await page.evaluate(() => document.fonts.ready);
const expected = fs.readFileSync('test-results/visual-home-desktop/home-expected.png');
const { PNG: P } = await import('pngjs');
const exp = P.sync.read(expected);
function diff(png, box) {
  let n=0;
  for (let y=box.y0;y<box.y1;y++) for (let x=box.x0;x<box.x1;x++) {
    const i=(y*png.width+x)*4, j=(y*exp.width+x)*4;
    const d=Math.max(Math.abs(png.data[i]-exp.data[j]),Math.abs(png.data[i+1]-exp.data[j+1]),Math.abs(png.data[i+2]-exp.data[j+2]));
    if (d>8) n++;
  }
  return n;
}
const box={x0:650,y0:1280,x1:1110,y1:1315};
// note: full page screenshot scroll offsets: element y from earlier includes scrollY? Use fullPage screenshot so doc coords
for (const w of [250,300,350,380,400,420,450,500,600,700]) {
  await page.addStyleTag({content:`.form-note{font-variation-settings:'wght' ${w} !important;}`});
  const buf = await page.screenshot({fullPage:true});
  const png = P.sync.read(buf);
  console.log('wght',w,'diff',diff(png,box));
}
await browser.close();
EOF
