const entries=[];
for(let i=0;i<numTables;i++){
  const flags=b[p++]; const idx=flags&0x3f; const tv=(flags>>6)&3;
  let tag;
  if(idx===0x3f){ tag=b.toString('ascii',p,p+4); p+=4; } else tag=TAGS[idx]||('idx'+idx);
  const origLength=base128();
  let transformed = tag==='glyf'||tag==='loca' ? (tv===0) : (tv!==0);
  let length=origLength;
  if(transformed) length=base128();
  entries.push({tag,origLength,length,transformed});
}
console.log(entries.map(e=>`${e.tag}:${e.origLength}${e.transformed?'/'+e.length:''}`).join(' '));
const comp=b.subarray(p, p+totalCompressedSize);
const raw=zlib.brotliDecompressSync(comp);
console.log('decompressed',raw.length);
let off=0;
const tables={};
for(const e of entries){tables[e.tag]=raw.subarray(off,off+e.length); off+=e.length;}
if(tables.fvar){
  const f=tables.fvar;
  console.log('fvar hdr', f.readUInt16BE(0), f.readUInt16BE(2),'axesOff',f.readUInt16BE(4),'count',f.readUInt16BE(8),'axisSize',f.readUInt16BE(10),'instances',f.readUInt16BE(12),'instSize',f.readUInt16BE(14));
  const axOff=f.readUInt16BE(4), count=f.readUInt16BE(8), size=f.readUInt16BE(10);
  for(let i=0;i<count;i++){
    const o=axOff+i*size;
    const tag=f.toString('ascii',o,o+4);
    const min=f.readInt32BE(o+4)/65536, def=f.readInt32BE(o+8)/65536, max=f.readInt32BE(o+12)/65536;
    console.log('axis',tag,min,def,max,'flags',f.readUInt16BE(o+16),'nameID',f.readUInt16BE(o+18));
  }
}
// name table for axis names
if(tables.name){
